-- Generated from the user-supplied 流通マスタ.csv. SHA-256: 204857434d701c1085af178475f2131dcb77037320faa4de21587998f86f5dc5
CREATE TABLE IF NOT EXISTS distribution_master (
 code TEXT PRIMARY KEY REFERENCES distribution_types(code), distribution_name TEXT NOT NULL, transaction_method TEXT NOT NULL, sales_type TEXT NOT NULL, notes TEXT NOT NULL, source_sha256 TEXT NOT NULL, source_row INTEGER NOT NULL
);
CREATE TRIGGER IF NOT EXISTS distribution_master_no_update BEFORE UPDATE ON distribution_master BEGIN SELECT RAISE(ABORT,'distribution master requires explicit migration'); END;
CREATE TRIGGER IF NOT EXISTS distribution_master_no_delete BEFORE DELETE ON distribution_master BEGIN SELECT RAISE(ABORT,'distribution master in use'); END;
